import calendar
from datetime import date, timedelta

_WEEKDAYS = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    if count <= 0:
        return []

    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        return [
            (start_date + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    if freq == "WEEKLY":
        weekdays = sorted({_WEEKDAYS[code] for code in parts[2].split(",")})
        week0_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while True:
            week_monday = week0_monday + timedelta(days=step * k * 7)
            for wd in weekdays:
                cand = week_monday + timedelta(days=wd)
                if cand >= start_date:
                    result.append(cand.isoformat())
                    if len(result) == count:
                        return result
            step += 1

    if freq == "MONTHLY":
        base_month = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(base_month + step * k, 12)
                month = month0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if 1 <= day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        result.append(cand.isoformat())
                step += 1
        else:
            nth = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(result) < count:
                year, month0 = divmod(base_month + step * k, 12)
                month = month0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if nth == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - target_wd) % 7
                else:
                    first_occ = 1 + (target_wd - first_wd) % 7
                    day = first_occ + (nth - 1) * 7
                if 1 <= day <= days_in_month:
                    cand = date(year, month, day)
                    if cand >= start_date:
                        result.append(cand.isoformat())
                step += 1
        return result

    if freq == "YEARLY":
        month_str, day_str = parts[2].split("-")
        month = int(month_str)
        day = int(day_str)
        step = 0
        while len(result) < count:
            year = start_date.year + step * k
            if 1 <= day <= calendar.monthrange(year, month)[1]:
                cand = date(year, month, day)
                if cand >= start_date:
                    result.append(cand.isoformat())
            step += 1
        return result

    raise ValueError(f"Unknown rule: {rule}")
